def hasCycle(self, n: int, edges: list[list[int]]) -> bool:
    adj: list[list[int]] = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
    color = [0] * n  # 0 white, 1 gray, 2 black

    def dfs(u: int) -> bool:
        color[u] = 1  # gray: on current path
        for v in adj[u]:
            if color[v] == 1:
                return True              # back edge → cycle
            if color[v] == 0 and dfs(v):
                return True
        color[u] = 2  # black: fully explored
        return False

    for i in range(n):
        if color[i] == 0 and dfs(i):
            return True
    return False

